//! XXH3 against the reference implementation, not against a table somebody typed.
//!
//! `tests/support/xxh3-vectors.txt` is generated by `scripts/xxh3-vectors.py`, which
//! calls `libxxhash` through ctypes and prints what it answered. The lengths cover every
//! boundary the algorithm's branches have (0, 1, 3, 4, 8, 9, 16, 17, 128, 129, 240, 241)
//! plus block edges on the long path and sizes in between, because a hash that is right
//! at the boundaries and wrong in the middle is a hash that is wrong.
//!
//! Regenerate it on a machine with the library and the table should not move; if it does,
//! either the library changed or something here did, and both are worth knowing.

use std::fs;
use std::path::Path;

fn pattern(n: usize) -> Vec<u8> {
    (0..n).map(|i| ((i * 7 + 3) % 251) as u8).collect()
}

fn vectors() -> Vec<(usize, String, String)> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/support/xxh3-vectors.txt");
    let text = fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    text.lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .map(|l| {
            let mut f = l.split_whitespace();
            let n: usize = f.next().expect("a length").parse().expect("a number");
            (
                n,
                f.next().expect("the 64-bit hex").to_string(),
                f.next().expect("the 128-bit hex").to_string(),
            )
        })
        .collect()
}

#[test]
fn the_whole_slice_agrees_with_the_reference_at_every_branch_boundary() {
    let v = vectors();
    assert!(
        v.len() > 40,
        "the vector table is too small to cover the branches: {} entries",
        v.len()
    );
    let mut widest = 0;
    for (n, want64, want128) in &v {
        let data = pattern(*n);
        assert_eq!(
            format!("{:016x}", rcp::xxh3::hash64(&data)),
            *want64,
            "XXH3-64 over {n} bytes"
        );
        assert_eq!(
            rcp::xxh3::hash128(&data).hex(),
            *want128,
            "XXH3-128 over {n} bytes"
        );
        widest = widest.max(*n);
    }
    // the long path is the one with state; a table that stopped before it would leave
    // the accumulator, the block scramble and the final stripe untested
    assert!(
        widest >= 4096,
        "no vector reaches the multi-block path: widest is {widest}"
    );
}

#[test]
fn a_stream_agrees_with_the_whole_slice_whatever_the_block_size() {
    // rcp reads a file in blocks, so the streaming digest is the one that actually runs.
    // XXH3's short paths are defined over the WHOLE input, and its long path reads its
    // final stripe from the END -- so a stream has to hold input back in one case and
    // reconstruct an overlapping stripe in the other. Neither is exercised by feeding it
    // all at once, which is what makes the block sizes here the point rather than noise:
    // 1 and 63 never fill a stripe, 64 fills exactly, 65 and 1000 straddle, and 1024 is a
    // whole block so the scramble lands on a feed boundary.
    for (n, want64, want128) in vectors() {
        let data = pattern(n);
        for chunk in [1usize, 7, 63, 64, 65, 128, 1000, 1024, 4096] {
            let mut h64 = rcp::xxh3::Xxh3::new(false);
            let mut h128 = rcp::xxh3::Xxh3::new(true);
            for part in data.chunks(chunk) {
                h64.update(part);
                h128.update(part);
            }
            assert_eq!(
                format!("{:016x}", h64.finish64()),
                want64,
                "XXH3-64 over {n} bytes in {chunk}-byte blocks"
            );
            assert_eq!(
                h128.finish128().hex(),
                want128,
                "XXH3-128 over {n} bytes in {chunk}-byte blocks"
            );
        }
        // and in one go, which is the degenerate case of the same thing
        let mut h = rcp::xxh3::Xxh3::new(false);
        h.update(&data);
        assert_eq!(h.hex(), want64, "XXH3-64 over {n} bytes in one feed");
    }
}

#[test]
fn the_control_is_that_a_wrong_digest_is_caught() {
    // The arms above compare against a file. A file that failed to load, or a comparison
    // that never ran, would be green -- so this plants a wrong answer and requires the
    // same comparison to reject it.
    let v = vectors();
    let (n, want64, _) = &v[v.len() / 2];
    let data = pattern(*n);
    let mut wrong = data.clone();
    wrong[*n / 2] ^= 1;
    assert_ne!(
        format!("{:016x}", rcp::xxh3::hash64(&wrong)),
        *want64,
        "one flipped bit gave the same digest over {n} bytes"
    );
    // and a truncated input is not the same as the whole one
    assert_ne!(
        format!(
            "{:016x}",
            rcp::xxh3::hash64(&data[..data.len().saturating_sub(1)])
        ),
        *want64
    );
}
